package com.google.javascript.jscomp;

import com.google.common.annotations.VisibleForTesting;
import com.google.common.base.Charsets;
import com.google.common.io.CharStreams;
import com.google.common.io.Files;
import com.google.javascript.jscomp.SourceFile;
import com.google.javascript.rhino.jstype.StaticSourceFile;
import java.io.*;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.Serializable;
import java.io.StringReader;
import java.math.*;
import java.nio.charset.Charset;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static com.google.javascript.jscomp.SourceFile.fromCode;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class SourceFile_getLineOffset_TriageGen1Test {

    @Test
    public void testGetLineOffset_ValidLines() {
        // Code with 3 lines
        // Line 1: "abc" (offset 0)
        // Line 2: "def" (offset 3)
        // Line 3: "ghi" (offset 6)
        String code = "abc\ndef\nghi";
        SourceFile sourceFile = fromCode("test.js", code);

        assertEquals(0, sourceFile.getLineOffset(1));
        assertEquals(3, sourceFile.getLineOffset(2));
        assertEquals(6, sourceFile.getLineOffset(3));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_LineTooLow() {
        String code = "line1\nline2";
        SourceFile sourceFile = fromCode("test.js", code);

        // lineno < 1
        sourceFile.getLineOffset(0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_LineTooHigh() {
        String code = "line1\nline2";
        SourceFile sourceFile = fromCode("test.js", code);

        // lineno > lineOffsets.length
        sourceFile.getLineOffset(3);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetLineOffset_NegativeLine() {
        String code = "line1";
        SourceFile sourceFile = fromCode("test.js", code);

        // lineno < 1 (negative)
        sourceFile.getLineOffset(-1);
    }

    @Test
    public void testGetLineOffset_LazyInitialization() {
        // This test ensures that the logic inside the 'if (lineOffsets == null)' 
        // branch is covered by calling the method for the first time.
        String code = "one\ntwo";
        SourceFile sourceFile = fromCode("test.js", code);

        // First call triggers findLineOffsets()
        int offset = sourceFile.getLineOffset(1);
        assertEquals(0, offset);

        // Second call uses cached lineOffsets
        assertEquals(4, sourceFile.getLineOffset(2));
    }

    @Test
    public void testGetLineOffset_SingleLine() {
        String code = "single";
        SourceFile sourceFile = fromCode("test.js", code);

        assertEquals(0, sourceFile.getLineOffset(1));
    }
}
